(()=>{'use strict';const toggle=document.querySelector('#menu-toggle'),header=document.querySelector('header'),nav=document.querySelector('#main-nav');function closeMenu(){header.classList.remove('nav-open');toggle.setAttribute('aria-expanded','false');toggle.querySelector('span').textContent='+'}toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';header.classList.toggle('nav-open',open);toggle.setAttribute('aria-expanded',String(open));toggle.querySelector('span').textContent=open?'−':'+'});nav.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});matchMedia('(min-width: 769px)').addEventListener('change',e=>{if(e.matches)closeMenu()});document.addEventListener('click',e=>{if(!header.contains(e.target))closeMenu()});document.addEventListener('caisik-clear-local',()=>document.dispatchEvent(new Event('caisik-learning-reset')));})();
// A compact, source-linked buying lesson; no fabricated product measurements.
(()=>{const essentials=document.querySelector('#essentials .faq-list');if(!essentials)return;const entry=document.createElement('details');entry.className='measure-guide';entry.innerHTML=`<summary>JAK ZMĚŘIT TRIKO NEBO MIKINU / PRAKTICKÝ NÁVOD</summary><div class="measure-layout"><svg viewBox="0 0 420 360" role="img" aria-label="Schéma měření: A je délka od ramene ke spodnímu lemu, B je šířka naplocho mezi podpažími"><path d="M150 45 95 70 40 145 100 185 125 150 125 320H295V150L320 185 380 145 325 70 270 45Q210 105 150 45Z" fill="#262f20" stroke="#9caa85" stroke-width="2"/><path d="M145 175H275M145 170V180M275 170V180M286 65V307M281 65H291M281 307H291" fill="none" stroke="#d6bc7e" stroke-width="3"/><g fill="#e6e3da" font-family="Arial" font-size="18"><text x="203" y="161">B</text><text x="303" y="195">A</text></g></svg><ol><li><strong>Polož oblíbený kus naplocho.</strong> Použij triko nebo mikinu, která ti už dobře sedí.</li><li><strong>B — šířka:</strong> měř mezi švy pod rukávy. Jde o šířku oděvu naplocho, nikoli obvod hrudníku.</li><li><strong>A — délka:</strong> měř od nejvyššího bodu u ramene ke spodnímu lemu podle návodu pro konkrétní model.</li><li><strong>Porovnej správnou tabulku.</strong> Míry oděvu porovnávej s mírami oděvu. Tabulka tělesných měr používá jiný způsob měření.</li></ol></div><p>Z označení S–3XL ani z náhledu nelze spolehlivě určit střih. Přesná tabulka musí odpovídat konkrétnímu produktu; tyto naměřené hodnoty tu zatím nemáme. Schéma je obecný návod, ne rozměrový výkres prodávaného kusu.</p><a class="text-button" href="https://www.printful.com/ca/blog/how-to-measure-a-t-shirt" target="_blank" rel="noopener">ZDROJ: PRINTFUL / HOW TO MEASURE A T-SHIRT ↗</a>`;essentials.prepend(entry)})();
